rb_time_timespec_new.prelude:
#include <mruby/time.h>
static mrb_value nfcx_time_timespec_new(mrb_state *mrb, const struct timespec *ts, int offset) {
  time_t sec = ts->tv_sec;
  time_t usec = ts->tv_nsec / 1000;
  if (offset == 0x7fffffff) return mrb_time_at(mrb, sec, usec, MRB_TIMEZONE_LOCAL);
  if (offset == 0x7ffffffe) return mrb_time_at(mrb, sec, usec, MRB_TIMEZONE_UTC);
  return mrb_time_at_offset(mrb, sec, usec, offset);
}

