rb_define_alloc_func.prelude:
/* BC2CPP-MRBGEM: a per-class allocator (rb_define_alloc_func). The fork has one global allocator, so the class's allocate
   and new are singleton methods that call the allocator registered for the class (or for a superclass). new is allocate
   followed by initialize with the same arguments and block, as Class#new. */
typedef mrb_value (*nfcx_alloc_fn)(mrb_state *, mrb_value);
static struct { struct RClass *c; nfcx_alloc_fn f; } nfcx_alloc_tab[64];
static int nfcx_alloc_n = 0;
static nfcx_alloc_fn
nfcx_alloc_for(struct RClass *c)
{
  for (; c; c = c->super) {
    int i;
    for (i = 0; i < nfcx_alloc_n; i++) {
      if (nfcx_alloc_tab[i].c == c) return nfcx_alloc_tab[i].f;
    }
  }
  return NULL;
}
static mrb_value
nfcx_alloc_allocate(mrb_state *mrb, mrb_value self)
{
  nfcx_alloc_fn f = nfcx_alloc_for(mrb_class_ptr(self));
  if (f == NULL) mrb_raise(mrb, E_RUNTIME_ERROR, "no allocator for this class");
  return f(mrb, self);
}
static mrb_value
nfcx_alloc_new(mrb_state *mrb, mrb_value self)
{
  mrb_value obj = nfcx_alloc_allocate(mrb, self);
  mrb_value *argv;
  mrb_int argc;
  mrb_value blk;
  mrb_get_args(mrb, "*&", &argv, &argc, &blk);
  mrb_funcall_with_block(mrb, obj, mrb_intern_lit(mrb, "initialize"), argc, argv, blk);
  return obj;
}
static void
nfcx_alloc_register(mrb_state *mrb, struct RClass *c, nfcx_alloc_fn f)
{
  if (nfcx_alloc_n >= 64) mrb_raise(mrb, E_RUNTIME_ERROR, "too many allocators");
  nfcx_alloc_tab[nfcx_alloc_n].c = c;
  nfcx_alloc_tab[nfcx_alloc_n].f = f;
  nfcx_alloc_n++;
  mrb_define_class_method(mrb, c, "allocate", nfcx_alloc_allocate, MRB_ARGS_NONE());
  mrb_define_class_method(mrb, c, "new", nfcx_alloc_new, MRB_ARGS_ANY());
}

rb_num_coerce_cmp.prelude:
static mrb_value nfcx_num_coerce_cmp(mrb_state *mrb, mrb_value x, mrb_value y, mrb_sym op) {
  mrb_value pair, a, b;
  if (!mrb_respond_to(mrb, y, mrb_intern_cstr(mrb, "coerce"))) return mrb_nil_value();
  pair = mrb_funcall_argv(mrb, y, mrb_intern_cstr(mrb, "coerce"), 1, &x);
  a = mrb_ary_ref(mrb, pair, 0); b = mrb_ary_ref(mrb, pair, 1);
  return mrb_funcall_argv(mrb, a, op, 1, &b);
}

rb_num_coerce_bin.prelude:
static mrb_value nfcx_num_coerce_bin(mrb_state *mrb, mrb_value x, mrb_value y, mrb_sym op) {
  mrb_value pair, a, b;
  pair = mrb_funcall_argv(mrb, y, mrb_intern_cstr(mrb, "coerce"), 1, &x);
  a = mrb_ary_ref(mrb, pair, 0); b = mrb_ary_ref(mrb, pair, 1);
  return mrb_funcall_argv(mrb, a, op, 1, &b);
}

rb_num_coerce_relop.prelude:
static mrb_value nfcx_num_coerce_relop(mrb_state *mrb, mrb_value x, mrb_value y, mrb_sym op) {
  mrb_value r = nfcx_num_coerce_cmp(mrb, x, y, op);
  if (mrb_nil_p(r)) mrb_raisef(mrb, E_ARGUMENT_ERROR, "comparison of %S with %S failed", mrb_str_new_cstr(mrb, mrb_obj_classname(mrb, x)), mrb_str_new_cstr(mrb, mrb_obj_classname(mrb, y)));
  return r;
}

rb_opts_exception_p.prelude:
static int nfcx_opts_exception_p(mrb_state *mrb, mrb_value opts, int default_value) {
  mrb_value key, v;
  if (!mrb_hash_p(opts)) return default_value;
  key = mrb_symbol_value(mrb_intern_cstr(mrb, "exception"));
  if (!mrb_hash_key_p(mrb, opts, key)) return default_value;
  v = mrb_hash_get(mrb, opts, key);
  if (mrb_true_p(v)) return 1;
  if (mrb_false_p(v)) return 0;
  mrb_raise(mrb, E_ARGUMENT_ERROR, "expected true or false as exception");
  return 0;
}

rb_memsearch.prelude:
#include <string.h>
static long nfcx_memsearch(const char *x, long m, const char *y, long n) {
  long i;
  if (m > n) return -1;
  if (m == 0) return 0;
  for (i = 0; i + m <= n; i++) if (memcmp(y + i, x, (size_t)m) == 0) return i;
  return -1;
}

rb_long2int.prelude:
