rb_get_kwargs.prelude:
static int nfcx_get_kwargs(mrb_state *mrb, mrb_value hash, const mrb_sym *ids, int required, int optional, mrb_value *values) {
  int i, n = required + optional, found = 0;
  for (i = 0; i < n; i++) {
    mrb_value key = mrb_symbol_value(ids[i]);
    if (mrb_hash_p(hash) && mrb_hash_key_p(mrb, hash, key)) {
      values[i] = mrb_hash_get(mrb, hash, key); found++;
    } else if (i < required) {
      mrb_raise(mrb, E_ARGUMENT_ERROR, "missing keyword");
    } else {
      values[i] = mrb_undef_value();
    }
  }
  return found;
}
